     1→// 🐀 Hash Chain Verifier - 기록이 위조되지 않았는가?
     2→// 목표: SHA256 체인으로 기록 무결성 검증 (100% integrity 필수)
     3→
     4→import * as crypto from 'crypto';
     5→
     6→export interface TestResult {
     7→  timestamp: number;
     8→  commit: string;
     9→  testName: string;
    10→  output: string;
    11→  exitCode: number;
    12→  hash?: string;
    13→  previousHash?: string;
    14→}
    15→
    16→export interface ChainVerificationResult {
    17→  isValid: boolean;
    18→  brokenAt?: number;
    19→  reason?: string;
    20→  totalLinks: number;
    21→  verifiedLinks: number;
    22→}
    23→
    24→export class HashChainVerifier {
    25→  private chain: TestResult[] = [];
    26→
    27→  // ============ SHA256 해시 계산 ============
    28→  private calculateHash(
    29→    timestamp: number,
    30→    commit: string,
    31→    testName: string,
    32→    output: string,
    33→    previousHash?: string
    34→  ): string {
    35→    // 해시 입력: previousHash (있으면) + timestamp + commit + testName + output
    36→    let input = '';
    37→
    38→    if (previousHash) {
    39→      input += previousHash;
    40→    }
    41→
    42→    input += `${timestamp}|${commit}|${testName}|${output}`;
    43→
    44→    return crypto.createHash('sha256').update(input).digest('hex');
    45→  }
    46→
    47→  // ============ 테스트 결과 기록 ============
    48→  recordTestResult(
    49→    timestamp: number,
    50→    commit: string,
    51→    testName: string,
    52→    output: string,
    53→    exitCode: number
    54→  ): TestResult {
    55→    // 이전 결과의 해시 구하기
    56→    const previousHash =
    57→      this.chain.length > 0 ? this.chain[this.chain.length - 1].hash : undefined;
    58→
    59→    // 현재 해시 계산
    60→    const hash = this.calculateHash(
    61→      timestamp,
    62→      commit,
    63→      testName,
    64→      output,
    65→      previousHash
    66→    );
    67→
    68→    const result: TestResult = {
    69→      timestamp,
    70→      commit,
    71→      testName,
    72→      output,
    73→      exitCode,
    74→      hash,
    75→      previousHash,
    76→    };
    77→
    78→    this.chain.push(result);
    79→    return result;
    80→  }
    81→
    82→  // ============ 체인 검증 ============
    83→  verifyChain(): ChainVerificationResult {
    84→    console.log('🐀 [HASH CHAIN VERIFIER] Verifying hash chain...\n');
    85→
    86→    if (this.chain.length === 0) {
    87→      return {
    88→        isValid: true,
    89→        totalLinks: 0,
    90→        verifiedLinks: 0,
    91→      };
    92→    }
    93→
    94→    let verifiedLinks = 0;
    95→    let brokenAt = -1;
    96→
    97→    for (let i = 0; i < this.chain.length; i++) {
    98→      const result = this.chain[i];
    99→
   100→      // i번째 결과의 해시 재계산
   101→      const recalculatedHash = this.calculateHash(
   102→        result.timestamp,
   103→        result.commit,
   104→        result.testName,
   105→        result.output,
   106→        result.previousHash
   107→      );
   108→
   109→      // 저장된 해시와 비교
   110→      if (recalculatedHash !== result.hash) {
   111→        console.log(
   112→          `❌ [BROKEN] Chain broken at link ${i}:`
   113→        );
   114→        console.log(
   115→          `   Expected: ${result.hash?.substring(0, 16)}...`
   116→        );
   117→        console.log(
   118→          `   Calculated: ${recalculatedHash.substring(0, 16)}...`
   119→        );
   120→        console.log(`   Test: ${result.testName}`);
   121→
   122→        brokenAt = i;
   123→        return {
   124→          isValid: false,
   125→          brokenAt,
   126→          reason: `Hash mismatch at link ${i} (${result.testName})`,
   127→          totalLinks: this.chain.length,
   128→          verifiedLinks,
   129→        };
   130→      }
   131→
   132→      verifiedLinks++;
   133→
   134→      // 이전 링크와의 연결 검증 (i > 0일 때)
   135→      if (i > 0) {
   136→        const prevResult = this.chain[i - 1];
   137→
   138→        // 현재 결과의 previousHash가 이전 결과의 hash와 일치하는가?
   139→        if (result.previousHash !== prevResult.hash) {
   140→          console.log(
   141→            `❌ [BROKEN] Chain link mismatch at position ${i}:`
   142→          );
   143→          console.log(
   144→            `   Expected previous: ${prevResult.hash?.substring(0, 16)}...`
   145→          );
   146→          console.log(
   147→            `   Actual previous: ${result.previousHash?.substring(0, 16)}...`
   148→          );
   149→
   150→          brokenAt = i;
   151→          return {
   152→            isValid: false,
   153→            brokenAt,
   154→            reason: `Chain link broken at ${i} (${result.testName})`,
   155→            totalLinks: this.chain.length,
   156→            verifiedLinks,
   157→          };
   158→        }
   159→      }
   160→    }
   161→
   162→    console.log(
   163→      `✅ Hash chain integrity verified: ${verifiedLinks}/${this.chain.length} links`
   164→    );
   165→
   166→    return {
   167→      isValid: true,
   168→      totalLinks: this.chain.length,
   169→      verifiedLinks,
   170→    };
   171→  }
   172→
   173→  // ============ 특정 위치의 해시 검증 ============
   174→  verifyAtIndex(index: number): boolean {
   175→    if (index < 0 || index >= this.chain.length) {
   176→      return false;
   177→    }
   178→
   179→    const result = this.chain[index];
   180→    const recalculatedHash = this.calculateHash(
   181→      result.timestamp,
   182→      result.commit,
   183→      result.testName,
   184→      result.output,
   185→      result.previousHash
   186→    );
   187→
   188→    return recalculatedHash === result.hash;
   189→  }
   190→
   191→  // ============ 체인 길이 ============
   192→  getChainLength(): number {
   193→    return this.chain.length;
   194→  }
   195→
   196→  // ============ 체인 내용 ============
   197→  getChain(): TestResult[] {
   198→    return this.chain;
   199→  }
   200→
   201→  // ============ 특정 테스트 결과 찾기 ============
   202→  findResult(testName: string): TestResult[] {
   203→    return this.chain.filter((r) => r.testName === testName);
   204→  }
   205→
   206→  // ============ 통계 ============
   207→  getStatistics() {
   208→    const stats = {
   209→      totalLinks: this.chain.length,
   210→      byTest: {} as Record<string, number>,
   211→      byCommit: {} as Record<string, number>,
   212→    };
   213→
   214→    for (const result of this.chain) {
   215→      stats.byTest[result.testName] = (stats.byTest[result.testName] || 0) + 1;
   216→      stats.byCommit[result.commit] = (stats.byCommit[result.commit] || 0) + 1;
   217→    }
   218→
   219→    return stats;
   220→  }
   221→
   222→  // ============ 해시 체인 시각화 ============
   223→  visualizeChain(): string {
   224→    let visualization = '';
   225→
   226→    for (let i = 0; i < this.chain.length; i++) {
   227→      const result = this.chain[i];
   228→      const hashDisplay = result.hash?.substring(0, 8) || 'NULL';
   229→
   230→      visualization += `Link ${i}: ${result.testName}@${result.commit}\n`;
   231→      visualization += `  Hash: ${hashDisplay}...\n`;
   232→
   233→      if (i < this.chain.length - 1) {
   234→        visualization += '  ↓\n';
   235→      }
   236→    }
   237→
   238→    return visualization;
   239→  }
   240→
   241→  // ============ 체인 데이터 저장/로드 ============
   242→  serializeChain(): string {
   243→    return JSON.stringify(this.chain, null, 2);
   244→  }
   245→
   246→  deserializeChain(jsonStr: string): void {
   247→    this.chain = JSON.parse(jsonStr);
   248→  }
   249→}
