     1→// 🐀 Differential Executor - 다양한 환경에서 일관성 검증
     2→// 목표: 다양한 환경에서 실행해도 결과가 같은가? (100% consistency 필수)
     3→
     4→export interface Environment {
     5→  name: string;
     6→  os: string;
     7→  arch: string;
     8→  version: string;
     9→}
    10→
    11→export interface ExecutionResult {
    12→  environment: Environment;
    13→  output: string;
    14→  exitCode: number;
    15→  executionTime: number;
    16→  memoryUsed: number;
    17→}
    18→
    19→export interface DifferentialReport {
    20→  isConsistent: boolean;
    21→  outputMatch: boolean;
    22→  exitCodeMatch: boolean;
    23→  performanceVariance: number; // %
    24→  memoryVariance: number; // %
    25→  environments: number;
    26→  results: ExecutionResult[];
    27→  issues: string[];
    28→}
    29→
    30→export class DifferentialExecutor {
    31→  private results: ExecutionResult[] = [];
    32→  private cachedEnvironment: Environment | null = null; // 환경 캐싱
    33→
    34→  // ============ 환경 정보 수집 ============
    35→  detectEnvironment(): Environment {
    36→    // 캐싱된 환경 재사용 (성능 개선)
    37→    if (this.cachedEnvironment) {
    38→      return this.cachedEnvironment;
    39→    }
    40→
    41→    this.cachedEnvironment = {
    42→      name: this.getEnvironmentName(),
    43→      os: process.platform,
    44→      arch: process.arch,
    45→      version: process.version,
    46→    };
    47→
    48→    return this.cachedEnvironment;
    49→  }
    50→
    51→  private getEnvironmentName(): string {
    52→    const platform = process.platform;
    53→    const arch = process.arch;
    54→
    55→    // platform과 arch 조합으로 이름 만들기
    56→    if (platform === 'linux') {
    57→      if (arch === 'x64') return 'Linux x86-64';
    58→      if (arch === 'arm64') return 'Linux ARM64';
    59→    } else if (platform === 'darwin') {
    60→      if (arch === 'x64') return 'macOS x86-64';
    61→      if (arch === 'arm64') return 'macOS ARM64 (M1)';
    62→    } else if (platform === 'win32') {
    63→      if (arch === 'x64') return 'Windows x86-64';
    64→    }
    65→
    66→    return `${platform}-${arch}`;
    67→  }
    68→
    69→  // ============ 테스트 실행 시뮬레이션 ============
    70→  recordExecution(
    71→    output: string,
    72→    exitCode: number,
    73→    executionTime: number,
    74→    memoryUsed: number
    75→  ): ExecutionResult {
    76→    const environment = this.detectEnvironment();
    77→
    78→    const result: ExecutionResult = {
    79→      environment,
    80→      output,
    81→      exitCode,
    82→      executionTime,
    83→      memoryUsed,
    84→    };
    85→
    86→    this.results.push(result);
    87→    return result;
    88→  }
    89→
    90→  // ============ 출력 일관성 검증 ============
    91→  private checkOutputConsistency(results: ExecutionResult[]): boolean {
    92→    if (results.length === 0) return true;
    93→
    94→    const firstOutput = results[0].output;
    95→
    96→    for (let i = 1; i < results.length; i++) {
    97→      if (results[i].output !== firstOutput) {
    98→        return false;
    99→      }
   100→    }
   101→
   102→    return true;
   103→  }
   104→
   105→  // ============ Exit Code 일관성 검증 ============
   106→  private checkExitCodeConsistency(results: ExecutionResult[]): boolean {
   107→    if (results.length === 0) return true;
   108→
   109→    const firstCode = results[0].exitCode;
   110→
   111→    for (let i = 1; i < results.length; i++) {
   112→      if (results[i].exitCode !== firstCode) {
   113→        return false;
   114→      }
   115→    }
   116→
   117→    return true;
   118→  }
   119→
   120→  // ============ 성능 분산 계산 (%) - 최적화 ============
   121→  private calculatePerformanceVariance(
   122→    results: ExecutionResult[]
   123→  ): number {
   124→    if (results.length < 2) return 0;
   125→
   126→    const times = results.map((r) => r.executionTime);
   127→    let sum = 0;
   128→    let min = Infinity;
   129→    let max = -Infinity;
   130→
   131→    // 단일 루프로 최적화
   132→    for (const time of times) {
   133→      sum += time;
   134→      if (time < min) min = time;
   135→      if (time > max) max = time;
   136→    }
   137→
   138→    const avg = sum / times.length;
   139→    const variance = max - min;
   140→
   141→    // 안정성을 위해 0.1% 최소값 추가
   142→    return Math.max((variance / avg) * 100, 0.1);
   143→  }
   144→
   145→  // ============ 메모리 분산 계산 (%) - 최적화 ============
   146→  private calculateMemoryVariance(results: ExecutionResult[]): number {
   147→    if (results.length < 2) return 0;
   148→
   149→    const memory = results.map((r) => r.memoryUsed);
   150→    let sum = 0;
   151→    let min = Infinity;
   152→    let max = -Infinity;
   153→
   154→    // 단일 루프로 최적화
   155→    for (const mem of memory) {
   156→      sum += mem;
   157→      if (mem < min) min = mem;
   158→      if (mem > max) max = mem;
   159→    }
   160→
   161→    const avg = sum / memory.length;
   162→    const variance = max - min;
   163→
   164→    return (variance / avg) * 100;
   165→  }
   166→
   167→  // ============ 전체 차등 분석 ============
   168→  generateDifferentialReport(): DifferentialReport {
   169→    console.log('🐀 [DIFFERENTIAL EXECUTOR] Analyzing results...\n');
   170→
   171→    const issues: string[] = [];
   172→
   173→    // 1. 출력 일관성
   174→    const outputMatch = this.checkOutputConsistency(this.results);
   175→    if (!outputMatch) {
   176→      issues.push('Output differs across environments');
   177→    }
   178→
   179→    // 2. Exit Code 일관성
   180→    const exitCodeMatch = this.checkExitCodeConsistency(this.results);
   181→    if (!exitCodeMatch) {
   182→      issues.push('Exit code differs across environments');
   183→    }
   184→
   185→    // 3. 성능 분산
   186→    const performanceVariance = this.calculatePerformanceVariance(
   187→      this.results
   188→    );
   189→    if (performanceVariance > 5) {
   190→      issues.push(
   191→        `Performance variance too high: ${performanceVariance.toFixed(2)}% (threshold: 5%)`
   192→      );
   193→    }
   194→
   195→    // 4. 메모리 분산
   196→    const memoryVariance = this.calculateMemoryVariance(this.results);
   197→    if (memoryVariance > 10) {
   198→      issues.push(
   199→        `Memory variance too high: ${memoryVariance.toFixed(2)}% (threshold: 10%)`
   200→      );
   201→    }
   202→
   203→    // 5. 환경 수
   204→    const environmentCount = new Set(
   205→      this.results.map((r) => r.environment.name)
   206→    ).size;
   207→
   208→    const isConsistent =
   209→      outputMatch &&
   210→      exitCodeMatch &&
   211→      performanceVariance <= 5 &&
   212→      memoryVariance <= 10;
   213→
   214→    const report: DifferentialReport = {
   215→      isConsistent,
   216→      outputMatch,
   217→      exitCodeMatch,
   218→      performanceVariance,
   219→      memoryVariance,
   220→      environments: environmentCount,
   221→      results: this.results,
   222→      issues,
   223→    };
   224→
   225→    this.printReport(report);
   226→    return report;
   227→  }
   228→
   229→  // ============ 보고서 출력 ============
   230→  private printReport(report: DifferentialReport): void {
   231→    console.log('📊 DIFFERENTIAL EXECUTION REPORT:\n');
   232→
   233→    for (const result of report.results) {
   234→      console.log(`Environment: ${result.environment.name}`);
   235→      console.log(`  Output: ${result.output.substring(0, 50)}...`);
   236→      console.log(`  Exit Code: ${result.exitCode}`);
   237→      console.log(
   238→        `  Time: ${result.executionTime}ms, Memory: ${result.memoryUsed}MB\n`
   239→      );
   240→    }
   241→
   242→    console.log('Consistency Checks:');
   243→    console.log(`  Output Match: ${report.outputMatch ? '✅' : '❌'}`);
   244→    console.log(`  Exit Code Match: ${report.exitCodeMatch ? '✅' : '❌'}`);
   245→    console.log(
   246→      `  Performance Variance: ${report.performanceVariance.toFixed(2)}% (threshold: 5%) ${report.performanceVariance <= 5 ? '✅' : '❌'}`
   247→    );
   248→    console.log(
   249→      `  Memory Variance: ${report.memoryVariance.toFixed(2)}% (threshold: 10%) ${report.memoryVariance <= 10 ? '✅' : '❌'}`
   250→    );
   251→    console.log(`  Environments Tested: ${report.environments}`);
   252→
   253→    if (report.issues.length > 0) {
   254→      console.log('\n⚠️  Issues:');
   255→      for (const issue of report.issues) {
   256→        console.log(`  - ${issue}`);
   257→      }
   258→    } else {
   259→      console.log('\n✅ All checks passed!');
   260→    }
   261→  }
   262→
   263→  // ============ 환경 정보 표시 ============
   264→  printEnvironmentInfo(): void {
   265→    const env = this.detectEnvironment();
   266→    console.log('Current Environment:');
   267→    console.log(`  Name: ${env.name}`);
   268→    console.log(`  OS: ${env.os}`);
   269→    console.log(`  Architecture: ${env.arch}`);
   270→    console.log(`  Version: ${env.version}`);
   271→  }
   272→
   273→  // ============ 통계 ============
   274→  getStatistics() {
   275→    const stats = {
   276→      totalRuns: this.results.length,
   277→      avgExecutionTime:
   278→        this.results.reduce((a, b) => a + b.executionTime, 0) /
   279→        this.results.length,
   280→      avgMemory:
   281→        this.results.reduce((a, b) => a + b.memoryUsed, 0) / this.results.length,
   282→      environments: new Set(this.results.map((r) => r.environment.name)).size,
   283→    };
   284→
   285→    return stats;
   286→  }
   287→
   288→  // ============ 결과 조회 ============
   289→  getResults(): ExecutionResult[] {
   290→    return this.results;
   291→  }
   292→}
